pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 a, uint256 b) public {
        // restrict to plausible range but keep it wide enough to expose the bug
        vm.assume(a <= type(uint256).max / 2);
        vm.assume(b <= type(uint256).max / 2);

        // owner calls AdjustDifficulty twice
        c.AdjustDifficulty(a);
        bool ok = true;
        try c.AdjustDifficulty(b) { ok = true; } catch { ok = false; }
        if (!ok) return; // second call reverted -> no finalization

        uint256 d = c.currentDifficulty();
        assertTrue(d == b);
    }
}

