pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), 0);
    }

    function testFuzz_property(uint256 difficultyAmount) public {
        vm.assume(difficultyAmount > 0);
        vm.assume(difficultyAmount < type(uint256).max);

        uint256 initialDifficulty = c.currentDifficulty();
        vm.assume(initialDifficulty != difficultyAmount);

        vm.recordLogs();
        c.AdjustDifficulty(difficultyAmount);
        Vm.Log[] memory entries = vm.getRecordedLogs();

        bool foundMatchingEvent = false;
        for (uint256 i = 0; i < entries.length; i++) {
            if (entries[i].emitter == address(c)) {
                uint256 recordedDifficulty = abi.decode(entries[i].data, (uint256));
                if (recordedDifficulty == difficultyAmount) {
                    foundMatchingEvent = true;
                    break;
                }
            }
        }

        assertTrue(foundMatchingEvent, "AdjustDifficulty must emit an event with the supplied amount");
    }
}

